solutionCode:
pub fn o_bilhete_da(resposta: Result<i32, String>) -> String {
    match resposta {
        Ok(n) => format!("bilhete: {}", n),
        Err(motivo) => motivo,
    }
}

pub fn o_embarque_de(poltrona: i32) -> Result<i32, String> {
    if poltrona < 0 {
        Err(String::from("poltrona negativa"))
    } else {
        Ok(poltrona)
    }
}

