use desafio::o_bilhete_da;
use desafio::o_embarque_de;

#[test]
fn testa_o_bilhete_da_poltrona_doze() {
    assert_eq!(o_bilhete_da(o_embarque_de(12)), String::from("bilhete: 12"));
}

#[test]
fn testa_o_bilhete_da_poltrona_negativa() {
    assert_eq!(o_bilhete_da(o_embarque_de(-3)), String::from("poltrona negativa"));
}
